import { expect, test, uniqueName } from "../../fixtures";

const TEN_MIB = 10 * 1024 * 1024;

test.describe("Upload vendor documents", () => {
  test("A file of exactly 10 MiB is accepted", { tag: "@DOC-05" }, async ({ apiAs }) => {
    // Arrange: signed in as a member, with a vendor in status "draft"
    const member = await apiAs("member");
    const createResponse = await member.post("/api/vendors", {
      data: {
        name: uniqueName("DOC-05 Vendor"),
        category: "services",
        contact_email: "billing@doc05vendor.test",
      },
    });
    expect(createResponse.status()).toBe(201);
    const vendor = await createResponse.json();
    expect(vendor.status).toBe("draft");

    const file = Buffer.alloc(TEN_MIB, "a");

    // Act: upload a text file of exactly 10 MiB as kind "contract"
    const response = await member.post(`/api/vendors/${vendor.id}/documents`, {
      multipart: {
        kind: "contract",
        file: {
          name: "contract-10mib.txt",
          mimeType: "text/plain",
          buffer: file,
        },
      },
    });

    // Assert
    expect(response.status()).toBe(201);
  });
});
